pub fn dlyfrzthw_threshold(hex_id: u64) -> Option<f32> {
    DLYFRZTHW_THRESHOLDS
        .binary_search_by_key(&hex_id, |entry| entry.0)
        .ok()
        .map(|idx| DLYFRZTHW_THRESHOLDS[idx].1 as f32 * THRESHOLD_SCALE)
}

