pub fn frost_days_threshold(hex_id: u64) -> Option<f32> {
    FROST_DAYS_THRESHOLDS
        .binary_search_by_key(&hex_id, |entry| entry.0)
        .ok()
        .map(|idx| FROST_DAYS_THRESHOLDS[idx].1 as f32 * THRESHOLD_SCALE)
}

