pub fn rx1day_threshold(hex_id: u64) -> Option<f32> {
    RX1DAY_THRESHOLDS
        .binary_search_by_key(&hex_id, |entry| entry.0)
        .ok()
        .map(|idx| RX1DAY_THRESHOLDS[idx].1 as f32 * THRESHOLD_SCALE)
}
